import React, { useState, useMemo, useEffect } from 'react';
// import ReactPlayer from 'react-player'

import bgVideoAsaya from '../media/home/Asaya.mp4';
import bgVideoReverie from '../media/home/Reverie.mp4';
import bgVideoShecommerz from '../media/home/Shecommerz.mp4'
import bgVideoNagwa from '../media/home/Nagwa.mp4';
import bgVideoSuaveMundane from '../media/home/suave.mp4'
import VideoRender from '../components/VideoRender';
import DefaultHeader from '../components/DefaultHeader';

const Home = () => {
  const divStyle = {
    position: 'absolute'
  };
  const [videoLinks] = useState([
    {
      videoData: bgVideoAsaya,
      title: 'Asaya - Welcome Home',
      // redirectLink: 'https://vimeo.com/856639345',
      fileName: 'Asaya.mp4'
    },
    {
      videoData: bgVideoReverie,
      title: 'REVERIE',
      fileName: 'Reverie.mp4'
  
    },
    {
      videoData: bgVideoShecommerz,
      title: 'She Commerz',
      fileName: 'Shecommerz.mp4'
    },
    {
      videoData: bgVideoNagwa,
      title: 'Nagwa x Hopo',
      fileName: 'Nagwa.mp4'
    },
    {
      videoData: bgVideoSuaveMundane,
      title: 'Suave Mundane',
      fileName: 'suave.mp4'
    }
  ])

  const [bgVideoIndex, setBgVideoIndex] = useState(null);
  const [bgVideoURL, setBgVideoURL] = useState(bgVideoAsaya);

  useEffect(() => {
    const cacheVideo = async () => {
      let fileReader, isCancel = false;
      if (Number.isInteger(bgVideoIndex)) {
        console.log(bgVideoIndex)
        const videoDataObj =  videoLinks[bgVideoIndex]
        const cachedVideoData = localStorage.getItem(videoDataObj.title);
        if (cachedVideoData) {
          console.log(videoDataObj.title+' yes')
          // Use cached video data
          setBgVideoURL(cachedVideoData);
        } else {
          // fileReader = new FileReader();
          // fileReader.onload = (e) => {
          //   const { result } = e.target;
          //   if (result && !isCancel) {
          //     var base64Data = result.split(",")[1];
          //     console.log(result);
          //     // Decode the base64 data
          //     var binaryData = atob(base64Data);

          //     // Create a blob from the binary data
          //     var blob = new Blob([binaryData], { type: 'video/mp4' });
          //     var videoUrl= window.URL.createObjectURL(blob);
          //     localStorage.setItem(videoDataObj.title, videoUrl);
          //     setBgVideoURL(videoUrl)
          //   }
          // }
          // fileReader.readAsDataURL(new File(['../media/home/Reverie.mp4'], videoDataObj.fileName, {
          //   type: "vedieo/mp4",
          // }));
          const response = await fetch(videoDataObj.videoData);
          if (response.ok) {
            const videoBlob = await response.blob();
            const videoUrl = URL.createObjectURL(videoBlob);
            // Cache video data
            localStorage.setItem(videoDataObj.title, videoUrl);
            setBgVideoURL(videoUrl);
          } else {
            console.error('Failed to fetch video:', response.status);
          }
        }
      }
    }
    cacheVideo();
    

  }, [bgVideoIndex]);

  return (
   <>
   {/* <DefaultHeader /> */}
   <section className='section overflow-hidden' id='home'>
       {/* <DefaultHeader /> */}
      {/* <ReactPlayer playing loop muted playsInline url='https://vimeo.com/730222592' width={'100%'} height={'100%'} style={divStyle}></ReactPlayer> */}
      
      <VideoRender srcLink={bgVideoURL} />
      
      <nav className="nav-lateral w-nav-menu">
        <div className='fixed m-h-[90vh] block'>
          <div className='navbar_project_list w-dyn-list'>
            <div role='list' className='navbar-collection-list'>
            {
              videoLinks.map((videoLink, index) => (
                <div role='listItem' className='navbar-collection-item films'>
                    <a href='' className='navlink_button films w-inline-block'>
                      <div class="bulletpoint">•</div>
                    </a>
                  </div>
              ))
            }
            </div>
          </div>
        </div>
      </nav>
      <div className='div-block-starting-page w-container'>
        {
          videoLinks.map((videoLink, index) => (
            <a key={index} onMouseEnter={() => setBgVideoIndex(index)} className='link-block w-inline-block' href={videoLink.redirectLink} target='_blank'>
              <div className='text-starting-david-alaba font-Namata hover:font-NamataItalic'>
                {videoLink.title}
              </div>
            </a>
          ))
        }
      </div>
    </section>
   </>
    
  );
};

export default Home;
