import React, { useState }from 'react';

import { fadeIn } from '../variants';

import g from '../img/about/g.png';
import Prithvi_Raj from '../img/about/Prithvi_Raj.jpeg';
import Tanmay_Biyani from '../img/about/Tanmay_Biyani.webp';
import Aravind_DOP from '../img/about/Aravind_DOP.jpg';
import Aswin from '../img/about/Aswin.jpg';
import Tiara from '../img/about/Tiara.jpeg';
import Dhruv_Kashyap from '../img/about/Dhruv_Kashyap.jpg';

// import logos
import vegNonVegLogo from '../img/logos/VegNonVeg.png';
import TO6Logo from '../img/logos/To6.png'
import demeLogo from '../img/logos/Deme.png'
import ModishLogo from '../img/logos/Modish.png'
import MokobaraLogo from '../img/logos/Mokobara.jpg'
import AsayaLogo from '../img/logos/Asaya.png'
import SimbaLogo from '../img/logos/Simba.png'
import SaykLogo from '../img/logos/Spy Hard Seltzer.png'
import keiflogo from '../img/logos/keif.webp'
import Nail_StationLogo from '../img/logos/Nail station.png'
import SculpLogo from '../img/logos/Sculp tattoos.png'
import DhahiaLogo from '../img/logos/Dhahia juice.png'
import Nothing from '../img/logos/Nothing.png';
import AcquaLogo from '../img/logos/Acqua.png';
import AtyabLogo from '../img/logos/Mello.png';
import ArnavLogo from '../img/logos/Arnav.PNG';

// import { Link } from 'react-router-dom';
// import  motion
import { motion } from 'framer-motion';
// import transition
import { transition1 } from '../transitions';
const About = () => {
  const row1Logos = [
    {
      title: '',
      image: vegNonVegLogo,
    },
    {
      title: '',
      image: TO6Logo,
    },
    {
      title: '',
      image: demeLogo,
    },
    {
      title: '',
      image: ModishLogo,
    },
    {
      title: '',
      image: MokobaraLogo,
    },
    {
      title: '',
      image: AsayaLogo,
    },
    {
      title: '',
      image: SimbaLogo,
    },
    {
      title: '',
      image: SaykLogo,
    }
  ];

  const row2Logos = [
    {
      title: '',
      image: keiflogo,
    },
    {
      title: '',
      image: Nail_StationLogo,
    },
    {
      title: '',
      image: SculpLogo,
    },
    {
      title: '',
      image: DhahiaLogo,
    },
    {
      title: '',
      image: Nothing,
    },
    {
      title: '',
      image: AcquaLogo,
    },
    {
      title: '',
      image: AtyabLogo,
    },
    {
      title: '',
      image: ArnavLogo,
    }
  ];

  

  const [collaborators] = useState([
    {
      rowID: '1',
      rowData: [
        {
          name: 'Gautam Monangi',
          role: 'Director',
          link: '',
          image: g
        },
        {
          name: 'Prithvi Raj',
          role: 'Producer',
          link: 'https://prithvi4960.notion.site/Prithvi-Raj-f2255719cdc54418bf5184165016a30d?pvs=4',
          image: Prithvi_Raj
        },
      ]
    },
    {
      rowID: '2',
      rowData: [
        {
          name: 'Tanmay Biyani',
          role: 'Producer. Founder of Clink Films.',
          link: 'https://www.clinkfilms',
          image: Tanmay_Biyani,
          style: 'w-[114px]'
        },
        {
          name: 'Aravind Yuvaraj',
          role: 'DOP',
          link: 'https://www.instagram.com/createdby.aravindhyuvaraj?igsh=NWtiZHI1Y3gwYWJm',
          image: Aravind_DOP
        },
      ]
    },
    {
      rowID: '3',
      rowData: [
        {
          name: 'Aswin Sumesh',
          role: 'DOP',
          link: 'http://linktr.ee/aswinsumesh',
          image: Aswin
        },
        {
          name: 'Tiara Turner',
          role: 'Writer',
          link: 'https://www.linkedin.com/in/tiara-turner-037242207/',
          image: Tiara
        },
      ]
    },
    {
      rowID: '4',
      rowData: [
        {
          name: 'Dhruv Kashyap',
          role: 'Business developer, Designer.',
          link: '',
          image: Dhruv_Kashyap,
          style: 'w-[100px]'
        }
      ]
    },
  ]);
  const [clients] = useState([
    {
      rowID: '1',
      rowData: [
        {
          name: 'Tanmay biyani from example films',
          image: g
        },
        {
          name: 'Arvind DOP',
          image: g
        },
      ]
    },
    {
      rowID: '2',
      rowData: [
        {
          name: 'Tanmay biyani from example films',
          image: g
        },
        {
          name: 'Arvind DOP',
          image: g
        },
      ]
    },
  ]);
  return <section id='about'
  className='section bg-white bg-cover h-[145vh]'>
    <div className='container mx-auto h-full relative'>
      {/* text & img wrapper */}
      <div className='flex flex-col lg:flex-col h-full gap-x-24
       text-center lg:text-left lg:pt-[10rem]'>
        {/* img*/}
        {/* <div className='flex-1 max-h-96 lg:max-h-max order-2 lg:order-none overflow-hidden'>
          <img src={g} />
        </div> */}
        {/* text */}
        <div
        className='flex-1 pt-36 pb-14 lg:pt-0 lg:w-auto z-10 flex flex-col items-center lg:items-start'>
          <motion.h1
          variants={fadeIn('right', 0.3)} initial="hidden"
          whileInView={'show'} viewport={{once: false, amount: 0.3}}
          transition={transition1}
          className='h1'>About Gautam Monangi Films</motion.h1>
          <motion.div 
          variants={fadeIn('down', 0.3)} initial="hidden"
          whileInView={'show'} viewport={{once: false, amount: 0.3}}
          transition={transition1}>
            <p className='mb-12 max-w-[50rem]'>
            Somewhere between trying to “sell” products and services, we often end up selling the story as well. Why is this far less profitable than it sounds? because if we look back into how human beings have survived, learnt, built ‘communities’ and evolved….it all comes down to one thing - well-told stories sell themselves.
            <br />
            <br />
            At Gautam Monangi Films, we believe in ‘show not sell’. In the right hands, commercial films could be just as memorable… just as artistic as cinema. So here we are, arms and lens wide open, ready to depict your story as aired before only in your vision
            <br />
            <br />
            GMF is your own personal community of creators, carefully brought together, waiting to create art out of that story - a souvenired invitation for your audience to keep and revisit, like a scene from their favourite movie, in the everyday moments of life.
            </p>
          </motion.div>
          
          <div className='lg:flex-1 mb-8'>
              <motion.h1 
              variants={fadeIn('right', 0.3)} initial="hidden"
              whileInView={'show'} viewport={{once: false, amount: 0.3}}
              transition={transition1}
              className='h2'>From our Community:</motion.h1>
              <div className='flex flex-col gap-y-4 max-w-[54rem] text-start'>
                  {
                    collaborators.map((collaboratorRow,index ) => (
                      <div key={collaboratorRow.rowID} className='flex gap-x-10'>
                        {
                          collaboratorRow.rowData.map((collaborator,index ) => (
                            <div className='flex-row flex w-[50%] gap-x-2'>
                              <div className={'w-[90px] '+collaborator.style}>
                                <img src={collaborator.image} />
                              </div>
                              <a href={collaborator.link} target='_blank'>
                                <div className='collaborator-name'>
                                  {collaborator.name}
                                </div>
                                <div>
                                  {collaborator.role}
                                </div>
                              </a>
                            </div>
                          ))
                        }
                      </div>
                    ))
                  }
              </div>
            </div>

            <div className='lg:flex-1 mb-8'>
              <motion.h1
              variants={fadeIn('right', 0.3)} initial="hidden"
              whileInView={'show'} viewport={{once: false, amount: 0.3}}
              transition={transition1}
              className='h2'>Clients</motion.h1>
              <div className='logosMarquee'>
                  <div className='logoMarqueeGroup1'>
                    {
                      row1Logos.map((row1Logo,index )  => (
                        <>
                          <imageGroup className='logosImageGroup'>
                            <img className='logoImage' key={index} src={row1Logo.image} />
                          </imageGroup>
                        </>
                      ))
                    }
                  </div>
                  <div className='logoMarqueeGroup1'>
                    {
                      row1Logos.map((row1Logo,index )  => (
                        <>
                          <imageGroup className='logosImageGroup'>
                            <img className='logoImage' key={index} src={row1Logo.image} />
                          </imageGroup>
                        </>
                      ))
                    }
                  </div>
              </div>
              <div className='logosMarquee'>
                  <div className='logoMarqueeGroup2'>
                    {
                      row2Logos.map((row2Logo,index )  => (
                        <>
                          <imageGroup key={index}
                          className='logosImageGroup'>
                            <img className='logoImage' key={index} src={row2Logo.image} />
                          </imageGroup>
                        </>
                      ))
                    }
                  </div>
                  <div className='logoMarqueeGroup2'>
                    {
                      row2Logos.map((row2Logo,index )  => (
                        <>
                          <imageGroup key={index}
                          className='logosImageGroup'>
                            <img className='logoImage' key={index} src={row2Logo.image} />
                          </imageGroup>
                        </>
                      ))
                    }
                  </div>
              </div>
            </div>
          {/* <Link to={'/work'} className='btn'>View my work</Link> */}
        </div>
      </div>
    </div>
  </section>;
};

export default About;
